const rows = $input.all();
if (!rows || rows.length === 0) return [];
const first = rows[0].json;
if (!first.waitlist_id) return [];
return rows;

const rows = items.map(i => { const x = i.json; const load = x.total_seats ? ((x.booked / x.total_seats) * 100).toFixed(1) : 0; return `${x.flight_number} | ${x.origin}→${x.destination} | ${x.dep_date} | Booked:${x.booked}/${x.total_seats}(${load}%) | Held:${x.held} | $${Number(x.revenue).toFixed(2)}`; });
const today = new Date().toISOString().split('T')[0];
